def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = max((c for c in counts if c != background), key=lambda c: counts[c])

    # Find the connected component forming the template, excluding markers.
    eligible = {
        (r, c)
        for r in range(h) for c in range(w)
        if grid[r][c] != background and grid[r][c] != marker
    }
    components = []
    while eligible:
        start = eligible.pop()
        comp = {start}
        q = [start]
        while q:
            r, c = q.pop()
            for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                if (nr, nc) in eligible:
                    eligible.remove((nr, nc))
                    comp.add((nr, nc))
                    q.append((nr, nc))
        components.append(comp)

    template = max(components, key=len)
    center = min(
        template,
        key=lambda p: sum(abs(p[0]-q[0]) + abs(p[1]-q[1]) for q in template)
    )
    offsets = [(r-center[0], c-center[1], grid[r][c]) for r, c in template]

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for dr, dc, color in offsets:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < h and 0 <= nc < w:
                        out[nr][nc] = color
    return out
